import{_ as a,a as o,o as t,ay as r}from"./chunks/framework.BUrXLeUq.js";const n="/open-pod/openpod_logo.svg",b=JSON.parse('{"title":"About Openpod","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"about.md","filePath":"about.md"}'),s={name:"about.md"};function i(d,e,h,p,l,c){return t(),o("div",null,e[0]||(e[0]=[r('<p><img src="'+n+'" alt="Openpod logo" class="op-page-logo"></p><h1 id="about-openpod" tabindex="-1">About Openpod <a class="header-anchor" href="#about-openpod" aria-label="Permalink to “About Openpod”">​</a></h1><p>Openpod is an open-source, iPod-style music player, built from scratch: the hardware, the firmware, the click wheel and the tools to load music on it.</p><h3 id="why" tabindex="-1">Why? <a class="header-anchor" href="#why" aria-label="Permalink to “Why?”">​</a></h3><p>Long story short: I don&#39;t have a smartphone, I loooove podcasts, and I am nostalgic about my old iPod, tragically stolen from me. I&#39;d rather build something myself than buy something I don&#39;t like.</p><h3 id="what-s-inside" tabindex="-1">What&#39;s inside? <a class="header-anchor" href="#what-s-inside" aria-label="Permalink to “What&#39;s inside?”">​</a></h3><p>An STM32F446 microcontroller, a 320×240 ILI9341 screen, a VS1053b audio decoder, 8 MB of PSRAM, a microSD card, a capacitive click wheel with haptics and a Bluetooth module. See the full <a href="/open-pod/#specs">specs and numbers on the home page</a>.</p><h3 id="where-is-it-at" tabindex="-1">Where is it at? <a class="header-anchor" href="#where-is-it-at" aria-label="Permalink to “Where is it at?”">​</a></h3><p>Everything runs on a breadboard prototype. The next steps are power management, a carrier PCB and then an iPod-sized board. The <a href="/open-pod/blog/">blog</a> follows the progress.</p>',9)]))}const u=a(s,[["render",i]]);export{b as __pageData,u as default};
